// פורמט קבוע (כמו הגרסה של ג׳מיני, 20.10.26): כותרת עם שם+תאריך+קלוריות, ארוחה = כותרת + "לבחור 1:" + ערכים ממוצעים, סיכום יומי בטבלה. הכל מימין לשמאל, בלי טווחים הפוכים
const avg = r => Math.round((r[0] + r[1]) / 2);
const K = Math.round(avg(M.tot.k) / 50) * 50, fullDate = Utilities.formatDate(new Date(), 'Asia/Jerusalem', 'dd.MM.yyyy');
const clean = t => String(t || '').replace(/\(([^)]*)\)/g, (m0, x) => '(' + x.replace(/\s*\/\s*/g, ', ') + ')').replace(/\s+/g, ' ').trim();
const doc = DocumentApp.create('תפריט ' + today + ' – ' + K + ' קלוריות');
const body = doc.getBody(); body.clear(); docInit_(body);
docPara_(body, 'תפריט תזונה — ' + name + ' · ' + fullDate + ' · ' + K.toLocaleString('en') + ' קלוריות', { h: DocumentApp.ParagraphHeading.HEADING1, bold: true, size: 20, color: DOC_.accent, after: 8 });
if (prefs && prefs.notes) docLbl_(body, 'הערות אישיות: ', String(prefs.notes).slice(0, 1500), { after: 6 });
M.meals.forEach(ml => {
  const rows = ml.rows.filter(r => r.opts.length); if (!rows.length) return;
  docH2_(body, ml.title);
  rows.forEach(r => { const lbl = String(r.label || '').trim();
    if (r.opts.length > 1) docLbl_(body, (lbl ? lbl + ' – ' : '') + 'לבחור 1: ', r.opts.slice(0, 8).map(o => clean(o.t)).join(' / '));
    else docLbl_(body, lbl ? lbl + ': ' : '', clean(r.opts[0].t)); });
  if (ml.note) docPara_(body, ml.note, { size: 10.5, color: DOC_.grey, before: 2, after: 2 });
  const R = ml.range; if (R && R.k && avg(R.k)) docLbl_(body, 'ערכים ממוצעים ל' + ml.title + ': ', 'כ-' + avg(R.k) + ' קלוריות | כ-' + avg(R.p) + ' גרם חלבון | כ-' + avg(R.c) + ' גרם פחמימות | כ-' + avg(R.f) + ' גרם שומן', { size: 10, color: DOC_.grey, before: 4 });
});
if (M.free) { docH2_(body, M.free + ' קלוריות חופשיות'); docPara_(body, 'לבחירה חופשית: חטיף, מתוק, משהו בחוץ. רושמים באפליקציה ביומן, תחת "חופשי" (אפשר לסרוק ברקוד). כבר נכללות בסיכום.', { size: 10.5 }); }
docPara_(body, 'סיכום ערכים תזונתיים יומי מוערך', { h: DocumentApp.ParagraphHeading.HEADING1, bold: true, size: 16, color: DOC_.accent, before: 16, after: 6 });
docTable_(body, ['רכיב תזונתי', 'כמות יומית מוערכת'], [['סה״כ קלוריות', 'כ-' + avg(M.tot.k).toLocaleString('en')], ['סה״כ חלבונים', 'כ-' + avg(M.tot.p) + ' גרם'], ['סה״כ פחמימות', 'כ-' + avg(M.tot.c) + ' גרם'], ['סה״כ שומנים', 'כ-' + avg(M.tot.f) + ' גרם']], [200, 220], { boldCols: [0] });
docPara_(body, 'ארוחות לא חייבות להיות בסדר הזה – העיקר שהכל נאכל עד סוף היום. אפשר לאחד ארוחות.', { italic: true, size: 10.5, color: DOC_.grey, before: 10 }); docRtlAll_(body);
